/* 
    محرك الألعاب الأسطوري 2D - المتاهة الأسطورية (إصدار المعتمد للـ 200 مرحلة)
    تم التطوير الكامل بواسطة: المبرمج معاذ محمد عبد النبي
    الميزات:
    - جرافيك واقعي مخصص (أشجار بلوط وصنوبر ضخمة تفصيلية، نباتات وعشيبات، خلفيات حية بالطيور والنجوم).
    - شخصية لاعب واقعية بتصميم فارس بشري كامل (درع، وشاح متحرك، شعر، وملامح حية).
    - أزرار الاتجاهات مضبوطة 100% (زر اليمين يتحرك يميناً وزر اليسار يتحرك يساراً).
    - محرك فيزياء عالي السلاسة يعمل على 60 فريم بدون تقطيع.
*/

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// --- حالات اللعبة العامة ---
let currentLevel = 1;
const maxLevels = 200;
let unlockedLevels = 1;
let coins = 0;
let gameRunning = false;
let gameLoopId = null;

let gameSettings = {
    brightness: 1.0,
    particlesEnabled: true,
    screenShake: true
};

// --- بيانات اللاعب الرئيسي (الفارس البشري Realistic Knight) ---
const player = {
    x: 80, y: 450,
    width: 40, height: 60,
    dx: 0, dy: 0,
    speed: 6.0, jumpPower: -13.5,
    isGrounded: false,
    hearts: 3, maxHearts: 5,
    ammo: 30,
    facing: 'right',
    animFrame: 0,
    animTimer: 0,
    invulnerable: false
};

// --- المجموعات الكائنية في العالم ---
let platforms = [];
let realisticTrees = [];
let groundPlants = [];
let backgroundBirds = [];
let backgroundStars = [];
let enemies = [];
let bullets = [];
let coinItems = [];
let levelGoal = { x: 1180, y: 400, width: 60, height: 90 };

const keys = { left: false, right: false, up: false, shoot: false };

// --- 1. توليد البيئة الحية والحيوانات الخلفية ---
function initBackgroundLife() {
    backgroundBirds = [];
    backgroundStars = [];

    // سحب غيوم وطيور خلفية متحركة
    for (let i = 0; i < 6; i++) {
        backgroundBirds.push({
            x: Math.random() * canvas.width,
            y: 40 + Math.random() * 140,
            speed: 1.2 + Math.random() * 1.5,
            wingAngle: 0,
            wingSpeed: 0.15 + Math.random() * 0.1
        });
    }

    // جزيئات غبار ونجوم ساطعة في الليل/الكهوف
    for (let i = 0; i < 40; i++) {
        backgroundStars.push({
            x: Math.random() * canvas.width,
            y: Math.random() * canvas.height * 0.6,
            radius: 1 + Math.random() * 2,
            alpha: Math.random()
        });
    }
}

// --- 2. مولد المراحل الضخم (200 مرحلة واقعية وتفصيلية) ---
function generateLevel(lvl) {
    platforms = [];
    realisticTrees = [];
    groundPlants = [];
    enemies = [];
    bullets = [];
    coinItems = [];

    player.x = 80; player.y = 450; player.dx = 0; player.dy = 0;

    // الأرضية الأساسية العريضة
    platforms.push({ x: 0, y: 530, width: 1280, height: 110, type: 'ground' });

    // تدرج في بناء المنصات المتطورة
    let platformCount = 4 + (lvl % 5);
    for (let i = 0; i < platformCount; i++) {
        let px = 220 + i * 200;
        let py = 410 - (i % 3) * 85;
        platforms.push({ x: px, y: py, width: 160, height: 26, type: 'platform' });

        // إضافة أشجار ضخمة واقعية فوق المنصات
        if ((i + lvl) % 2 === 0) {
            realisticTrees.push({
                x: px + 80, y: py,
                type: (i % 2 === 0) ? 'oak' : 'pine',
                scale: 0.9 + Math.random() * 0.3
            });
        }

        // إدراج عملات ذهبية
        coinItems.push({ x: px + 75, y: py - 35, width: 18, height: 18, collected: false });
    }

    // أشجار ضخمة واقعية ومزروعات غناء على الأرضية الرئيسية
    realisticTrees.push({ x: 140, y: 530, type: 'oak', scale: 1.4 });
    realisticTrees.push({ x: 620, y: 530, type: 'pine', scale: 1.5 });
    realisticTrees.push({ x: 1040, y: 530, type: 'oak', scale: 1.3 });

    // مزروعات شجيرات وشذرات على الأرضية
    for (let g = 50; g < 1200; g += 80) {
        groundPlants.push({
            x: g + Math.random() * 30,
            y: 530,
            height: 12 + Math.random() * 16,
            type: Math.random() > 0.5 ? 'grass_tuft' : 'bush'
        });
    }

    // توليد الوحوش التفصيلية الصعبة
    let enemyCount = 2 + Math.floor(lvl / 6);
    for (let e = 0; e < enemyCount; e++) {
        let ex = 320 + e * 220;
        let isStrong = (e + lvl) % 2 === 0;

        enemies.push({
            x: ex, y: 475,
            width: isStrong ? 46 : 38,
            height: isStrong ? 55 : 38,
            type: isStrong ? 'orc' : 'slime',
            hp: isStrong ? 2 : 1,
            maxHp: isStrong ? 2 : 1,
            speed: (1.6 + (e * 0.25)) * (1 + lvl * 0.008),
            dir: 1,
            range: [ex - 90, ex + 90]
        });
    }

    initBackgroundLife();
}

// --- 3. حركة اللاعب المحسنة والتصادمات الدقيقة ---
function update() {
    if (!gameRunning) return;

    // حركة أفقیة مضبوطة (زر اليمين يزود X وزر اليسار ينقص X)
    if (keys.left) { player.dx = -player.speed; player.facing = 'left'; }
    else if (keys.right) { player.dx = player.speed; player.facing = 'right'; }
    else { player.dx = 0; }

    // القفز السلس
    if (keys.up && player.isGrounded) {
        player.dy = player.jumpPower;
        player.isGrounded = false;
    }

    // الجاذبية والتنقل
    player.dy += 0.65;
    player.x += player.dx;
    player.y += player.dy;

    // حدود الشاشة
    if (player.x < 0) player.x = 0;
    if (player.x + player.width > canvas.width) player.x = canvas.width - player.width;

    // التصادم مع المنصات والأرضية
    player.isGrounded = false;
    platforms.forEach(p => {
        if (player.x < p.x + p.width && player.x + player.width > p.x &&
            player.y + player.height >= p.y && player.y + player.height <= p.y + p.height && player.dy >= 0) {
            player.y = p.y - player.height;
            player.dy = 0;
            player.isGrounded = true;
        }
    });

    // تحديث الرصاص وقذائف القتال
    bullets.forEach((b, idx) => {
        b.x += b.speed;
        if (b.x > canvas.width || b.x < 0) bullets.splice(idx, 1);
    });

    // جمع العملات
    coinItems.forEach(c => {
        if (!c.collected && player.x < c.x + c.width && player.x + player.width > c.x &&
            player.y < c.y + c.height && player.y + player.height > c.y) {
            c.collected = true;
            coins += 5;
        }
    });

    // تحديث حركة طيور الخلفية الحية
    backgroundBirds.forEach(bird => {
        bird.x += bird.speed;
        bird.wingAngle += bird.wingSpeed;
        if (bird.x > canvas.width + 50) bird.x = -50;
    });

    // تحديث حركة الوحوش وتصادمها مع اللاعب
    enemies.forEach((e, eIdx) => {
        e.x += e.speed * e.dir;
        if (e.x < e.range[0] || e.x > e.range[1]) e.dir *= -1;

        // الرصاص يصيب الوحش
        bullets.forEach((b, bIdx) => {
            if (b.x > e.x && b.x < e.x + e.width && b.y > e.y && b.y < e.y + e.height) {
                e.hp--;
                bullets.splice(bIdx, 1);
                if (e.hp <= 0) enemies.splice(eIdx, 1);
            }
        });

        // تصادم الوحش مع اللاعب أو دهس الوحش من الأعلى
        if (player.x < e.x + e.width && player.x + player.width > e.x &&
            player.y < e.y + e.height && player.y + player.height > e.y) {
            
            if (player.dy > 0 && player.y + player.height - player.dy <= e.y + 15) {
                enemies.splice(eIdx, 1); // دهس الوحش الأسطوري
                player.dy = player.jumpPower * 0.7;
                coins += 10;
            } else if (!player.invulnerable) {
                player.hearts--;
                player.invulnerable = true;
                player.x = 80; player.y = 450;
                
                setTimeout(() => { player.invulnerable = false; }, 1200);

                if (player.hearts <= 0) {
                    gameRunning = false;
                    document.getElementById('loseMenu').classList.remove('hidden');
                }
            }
        }
    });

    // الوصول لباب خروج المرحلة الحجري الواقعي
    if (player.x < levelGoal.x + levelGoal.width && player.x + player.width > levelGoal.x &&
        player.y < levelGoal.y + levelGoal.height && player.y + player.height > levelGoal.y) {
        gameRunning = false;
        if (currentLevel >= unlockedLevels) unlockedLevels = Math.min(maxLevels, currentLevel + 1);
        document.getElementById('winSummaryText').innerText = `جمعت عملات في هذه المرحلة! رصيدك الحالي: ${coins} 🪙`;
        document.getElementById('winMenu').classList.remove('hidden');
    }
}

// --- 4. الرسم البصري الواقعي والمجسم (Realistic Graphic Render) ---

// رسم الأشجار الضخمة الواقعية التفصيلية (بلوط وصنوبر)
function drawRealisticTree(x, groundY, type, scale) {
    ctx.save();
    ctx.translate(x, groundY);
    ctx.scale(scale, scale);

    if (type === 'oak') {
        // جذع الشجرة الضخم المتشعب
        ctx.fillStyle = '#451a03';
        ctx.beginPath();
        ctx.moveTo(-15, 0);
        ctx.lineTo(-12, -60);
        ctx.lineTo(-30, -90);
        ctx.lineTo(-18, -95);
        ctx.lineTo(-5, -70);
        ctx.lineTo(10, -90);
        ctx.lineTo(20, -85);
        ctx.lineTo(8, -60);
        ctx.lineTo(12, 0);
        ctx.closePath();
        ctx.fill();

        // لحاء خشب الجذع
        ctx.strokeStyle = '#78350f';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-8, -10); ctx.lineTo(-6, -50);
        ctx.moveTo(3, -15); ctx.lineTo(5, -55);
        ctx.stroke();

        // أوراق البلوط الضخمة متعددة الطبقات والتدرجات الظلية
        const oakFoliage = [
            { x: -35, y: -110, r: 35, color: '#14532d' },
            { x: 30, y: -110, r: 35, color: '#15803d' },
            { x: 0, y: -140, r: 45, color: '#166534' },
            { x: -20, y: -130, r: 30, color: '#22c55e' },
            { x: 20, y: -130, r: 30, color: '#4ade80' }
        ];

        oakFoliage.forEach(f => {
            ctx.fillStyle = f.color;
            ctx.beginPath();
            ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
            ctx.fill();
        });
    } else {
        // شجرة الصنوبر الصنوبرية الضخمة Cone Tree
        ctx.fillStyle = '#291d09';
        ctx.fillRect(-10, -50, 20, 50);

        // طبقات الصنوبر الحادة المتداخلة
        const pineLayers = [
            { bottomY: -35, topY: -85, width: 70, color: '#064e3b' },
            { bottomY: -70, topY: -120, width: 55, color: '#047857' },
            { bottomY: -105, topY: -155, width: 40, color: '#10b981' }
        ];

        pineLayers.forEach(l => {
            ctx.fillStyle = l.color;
            ctx.beginPath();
            ctx.moveTo(-l.width / 2, l.bottomY);
            ctx.lineTo(0, l.topY);
            ctx.lineTo(l.width / 2, l.bottomY);
            ctx.closePath();
            ctx.fill();
        });
    }

    ctx.restore();
}

// رسم الباب الحجري الخروجي الواقعي (Realistic Ancient Stone Archway)
function drawRealisticDoor(x, y, w, h) {
    ctx.save();

    // القوس الحجري الخارجي
    ctx.fillStyle = '#334155';
    ctx.beginPath();
    ctx.arc(x + w / 2, y + 30, w / 2 + 8, Math.PI, 0);
    ctx.fillRect(x - 8, y + 30, w + 16, h - 30);
    ctx.fill();

    // أحجار القوس التفصيلية
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 3;
    ctx.stroke();

    // تجويف الباب الخشبي الداخلي
    ctx.fillStyle = '#451a03';
    ctx.fillRect(x, y + 25, w, h - 25);
    ctx.beginPath();
    ctx.arc(x + w / 2, y + 25, w / 2, Math.PI, 0);
    ctx.fill();

    // خطوط الألواح الخشبية ومقبض الباب الذهبي
    ctx.strokeStyle = '#292524';
    ctx.lineWidth = 2;
    for (let lx = x + 12; lx < x + w; lx += 12) {
        ctx.beginPath();
        ctx.moveTo(lx, y + 15);
        ctx.lineTo(lx, y + h);
        ctx.stroke();
    }

    // مقبض الباب والمشعل المضيء فوقه
    ctx.fillStyle = '#fbbf24';
    ctx.beginPath();
    ctx.arc(x + w - 12, y + h / 2 + 5, 5, 0, Math.PI * 2);
    ctx.fill();

    // ضوء توهج الباب 💡
    ctx.fillStyle = 'rgba(251, 191, 36, 0.15)';
    ctx.beginPath();
    ctx.arc(x + w / 2, y + h / 2, w, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
}

// رسم الفارس البشري الواقعي (Realistic Human Knight Player)
function drawRealisticPlayer(p) {
    ctx.save();
    ctx.translate(p.x, p.y);

    if (p.facing === 'left') {
        ctx.scale(-1, 1);
        ctx.translate(-p.width, 0);
    }

    // 1. الوشاح الخلفي المنسدل المتحرك
    ctx.fillStyle = '#dc2626';
    ctx.beginPath();
    ctx.moveTo(8, 20);
    ctx.lineTo(-10, 45);
    ctx.lineTo(12, 55);
    ctx.lineTo(20, 22);
    ctx.closePath();
    ctx.fill();

    // 2. الساقين والدرع السفلي (Greaves)
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(8, 38, 10, 22);
    ctx.fillRect(22, 38, 10, 22);

    // 3. درع الصدر الفولاذي المجسم (Armor Chestplate)
    let armorGrad = ctx.createLinearGradient(5, 15, 30, 40);
    armorGrad.addColorStop(0, '#94a3b8');
    armorGrad.addColorStop(0.5, '#475569');
    armorGrad.addColorStop(1, '#334155');
    ctx.fillStyle = armorGrad;
    ctx.fillRect(6, 16, 28, 24);

    // حزام الفارس الذهبي
    ctx.fillStyle = '#d97706';
    ctx.fillRect(6, 36, 28, 4);

    // 4. الرأس والبشرة والشعر الحقيقي
    ctx.fillStyle = '#fbcfe8'; // لون البشرة
    ctx.beginPath();
    ctx.arc(20, 10, 10, 0, Math.PI * 2);
    ctx.fill();

    // الشعر البني الحقيقي
    ctx.fillStyle = '#451a03';
    ctx.beginPath();
    ctx.arc(19, 7, 11, Math.PI, 0);
    ctx.fill();

    // العين وتفاصيل الوجه
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(24, 8, 3, 3);

    // 5. السيف القتالي بيد الفارس ⚔️
    ctx.fillStyle = '#cbd5e1';
    ctx.fillRect(32, 10, 4, 28); // نصل السيف
    ctx.fillStyle = '#fbbf24';
    ctx.fillRect(29, 26, 10, 4); // مقبض السيف

    ctx.restore();
}

// رسم الوحوش المتقدمة (سلايم وأورك واقعي)
function drawAdvancedEnemies() {
    enemies.forEach(e => {
        if (e.type === 'slime') {
            // سلايم نبضي بفقاعات مضيئة
            ctx.fillStyle = '#10b981';
            ctx.beginPath();
            ctx.arc(e.x + e.width / 2, e.y + e.height - 12, 20, Math.PI, 0);
            ctx.fill();
            ctx.fillStyle = '#ecfdf5';
            ctx.beginPath();
            ctx.arc(e.x + 12, e.y + e.height - 22, 4, 0, Math.PI * 2);
            ctx.arc(e.x + 26, e.y + e.height - 22, 4, 0, Math.PI * 2);
            ctx.fill();
        } else {
            // وحش الأورك الضخم بقرون وبار صحة تفصيلي
            ctx.fillStyle = '#b91c1c';
            ctx.fillRect(e.x, e.y + 12, e.width, e.height - 12);
            
            // قرون الأورك الوحشية
            ctx.fillStyle = '#f59e0b';
            ctx.beginPath();
            ctx.moveTo(e.x + 8, e.y + 12); ctx.lineTo(e.x - 2, e.y - 4); ctx.lineTo(e.x + 16, e.y + 12);
            ctx.moveTo(e.x + e.width - 8, e.y + 12); ctx.lineTo(e.x + e.width + 2, e.y - 4); ctx.lineTo(e.x + e.width - 16, e.y + 12);
            ctx.fill();

            // شريط الصحة المجسم فوق الوحش
            ctx.fillStyle = '#000';
            ctx.fillRect(e.x, e.y - 10, e.width, 6);
            ctx.fillStyle = '#22c55e';
            ctx.fillRect(e.x, e.y - 10, (e.width * (e.hp / e.maxHp)), 6);
        }
    });
}

// --- 5. حلقة الرسم الرئيسية للمحرك Render Loop ---
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // خلفية السماء الليلية التدرجية الواقعية
    let skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
    skyGrad.addColorStop(0, '#020617');
    skyGrad.addColorStop(0.7, '#0f172a');
    skyGrad.addColorStop(1, '#1e1b4b');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // رسم نجوم خلفية حية مضيئة
    backgroundStars.forEach(s => {
        ctx.fillStyle = `rgba(255, 255, 255, ${s.alpha})`;
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
        ctx.fill();
    });

    // رسم الطيور الحية المتحركة في خلفية السماء 🦅
    ctx.strokeStyle = 'rgba(226, 232, 240, 0.6)';
    ctx.lineWidth = 2;
    backgroundBirds.forEach(b => {
        ctx.beginPath();
        ctx.moveTo(b.x, b.y);
        ctx.lineTo(b.x + 8, b.y + Math.sin(b.wingAngle) * 6);
        ctx.lineTo(b.x + 16, b.y);
        ctx.stroke();
    });

    // رسم البلاتفورم والأرضيات الحجرية العشبية
    platforms.forEach(p => {
        ctx.fillStyle = p.type === 'ground' ? '#1e293b' : '#334155';
        ctx.fillRect(p.x, p.y, p.width, p.height);
        // حافة عشبية مزروعة فوق كل منصة
        ctx.fillStyle = '#10b981';
        ctx.fillRect(p.x, p.y, p.width, 6);
    });

    // رسم المزروعات والشجيرات الأرضية
    groundPlants.forEach(plant => {
        ctx.fillStyle = '#059669';
        ctx.beginPath();
        ctx.arc(plant.x, plant.y, plant.height, Math.PI, 0);
        ctx.fill();
    });

    // رسم الأشجار الواقعية التفصيلية
    realisticTrees.forEach(t => drawRealisticTree(t.x, t.y, t.type, t.scale));

    // رسم العملات الذهبية
    coinItems.forEach(c => {
        if (!c.collected) {
            ctx.fillStyle = '#fbbf24';
            ctx.beginPath();
            ctx.arc(c.x + 9, c.y + 9, 9, 0, Math.PI * 2);
            ctx.fill();
        }
    });

    // رسم الباب الحجري الواقعي
    drawRealisticDoor(levelGoal.x, levelGoal.y, levelGoal.width, levelGoal.height);

    // رسم اللاعب والوحوش القتالية
    drawRealisticPlayer(player);
    drawAdvancedEnemies();

    // رسم قذائف السيف والرصاص
    ctx.fillStyle = '#fbbf24';
    bullets.forEach(b => ctx.fillRect(b.x, b.y, 14, 5));

    // شريط المعلومات المتكامل HUD
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 20px Segoe UI, sans-serif';
    ctx.fillText(`المرحلة: ${currentLevel} / ${maxLevels}`, 30, 40);
    ctx.fillText(`القلوب: ${"❤️".repeat(player.hearts)}`, 30, 75);
    ctx.fillText(`الذخيرة: ${player.ammo} 🔫`, 30, 110);
    ctx.fillText(`العملات: ${coins} 🪙`, 30, 145);
}

function mainLoop() {
    update();
    render();
    gameLoopId = requestAnimationFrame(mainLoop);
}

// --- 6. الإدارات وأجهزة التحكم باللمس واللوحة ---
function shoot() {
    if (player.ammo > 0) {
        bullets.push({
            x: player.facing === 'right' ? player.x + player.width : player.x - 14,
            y: player.y + 22,
            speed: player.facing === 'right' ? 12 : -12
        });
        player.ammo--;
    }
}

function startGame() {
    document.getElementById('mainMenu').classList.add('hidden');
    generateLevel(currentLevel);
    gameRunning = true;
}

function nextLevel() {
    currentLevel++;
    if (currentLevel > maxLevels) currentLevel = 1;
    document.getElementById('winMenu').classList.add('hidden');
    generateLevel(currentLevel);
    gameRunning = true;
}

function restartLevel() {
    player.hearts = 3; player.ammo = 30;
    document.getElementById('loseMenu').classList.add('hidden');
    generateLevel(currentLevel);
    gameRunning = true;
}

function openLevelSelect() {
    const grid = document.getElementById('levelGrid');
    grid.innerHTML = '';
    for (let i = 1; i <= maxLevels; i++) {
        const card = document.createElement('div');
        card.className = `level-card ${i <= unlockedLevels ? '' : 'locked'}`;
        card.innerText = i;
        if (i <= unlockedLevels) {
            card.onclick = () => {
                currentLevel = i;
                closeOverlay('levelMenu');
                startGame();
            };
        }
        grid.appendChild(card);
    }
    document.getElementById('levelMenu').classList.remove('hidden');
}

function openShop() {
    document.getElementById('shopCoinsDisplay').innerText = coins;
    document.getElementById('shopMenu').classList.remove('hidden');
}

function buyAmmo() { if (coins >= 15) { coins -= 15; player.ammo += 10; openShop(); } }
function buyHeart() { if (coins >= 30 && player.hearts < player.maxHearts) { coins -= 30; player.hearts++; openShop(); } }
function upgradeSpeed() { if (coins >= 60) { coins -= 60; player.speed += 0.8; openShop(); } }

function openSettings() { document.getElementById('settingsMenu').classList.remove('hidden'); }
function closeOverlay(id) { document.getElementById(id).classList.add('hidden'); }
function showMainMenu() {
    document.getElementById('winMenu').classList.add('hidden');
    document.getElementById('loseMenu').classList.add('hidden');
    document.getElementById('mainMenu').classList.remove('hidden');
    gameRunning = false;
}

function applySettings() {
    gameSettings.brightness = document.getElementById('brightnessControl').value / 100;
}

// ربط أزرار التحكم اللمسية (زر اليسار وزر اليمين في مكانهما الصحيح بدون أي عكس)
document.getElementById('btnLeft').ontouchstart = (e) => { e.preventDefault(); keys.left = true; };
document.getElementById('btnLeft').ontouchend = (e) => { e.preventDefault(); keys.left = false; };
document.getElementById('btnRight').ontouchstart = (e) => { e.preventDefault(); keys.right = true; };
document.getElementById('btnRight').ontouchend = (e) => { e.preventDefault(); keys.right = false; };
document.getElementById('btnJump').ontouchstart = (e) => { e.preventDefault(); keys.up = true; };
document.getElementById('btnJump').ontouchend = (e) => { e.preventDefault(); keys.up = false; };
document.getElementById('btnShoot').onclick = () => shoot();

window.onkeydown = e => {
    if (e.key === 'ArrowLeft') keys.left = true;
    if (e.key === 'ArrowRight') keys.right = true;
    if (e.key === 'ArrowUp') keys.up = true;
    if (e.key === ' ') shoot();
};
window.onkeyup = e => {
    if (e.key === 'ArrowLeft') keys.left = false;
    if (e.key === 'ArrowRight') keys.right = false;
    if (e.key === 'ArrowUp') keys.up = false;
};

mainLoop();

